			const numNew = floor(d / (MIN_CIRCLE_SIZE * 2.5))
			let cx = lastManuallyAddedCircle[0]
			let cy = lastManuallyAddedCircle[1]
			for (let i=0; i<numNew; i++) {
				cx += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - lastManuallyAddedCircle[0]) / numNew
				cy += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - lastManuallyAddedCircle[1]) / numNew
				circle(cx, cy, 4)
				bestCircles.push([cx, cy, 4])
			}
		} else {
